/**
 * __NAME__ — generated by `uniplug init --template advanced`.
 *
 * A complete plugin skeleton wiring every major feature. Delete what you
 * do not need; the pieces are independent.
 */

import { definePlugin } from '__IMPORT__';

export default definePlugin({
  setup(api) {
    // 1. service: other plugins reach it with api.use('__ID__')
    api.provide('__ID__', {
      status: () => ({ ok: true, startedAt: this?.startedAt ?? null }),
    });

    // 2. event: react to a domain event
    api.on('__ID__:request', async (payload) => {
      api.log.debug('request', payload);
      return { handled: true, payload };
    });

    // 3. middleware: transform a pipeline value
    api.hook('__ID__:pipeline', async (value, next) => {
      value.steps.push('__ID__');
      const result = await next(value);
      result.touchedBy = '__ID__';
      return result;
    });

    // 4. command
    api.command(
      '__ID__:status',
      async () => {
        const runs = await api.store.get('runs', 0);
        return { runs, intervalMs: api.config.get('intervalMs'), plugins: api.plugins() };
      },
      'Report plugin status',
    );

    // 5. storage + timer (timers are cleared automatically on disable)
    api.poll(api.config.get('intervalMs', 10000), async () => {
      await api.store.update('runs', (n) => (n || 0) + 1);
      if (api.config.get('verbose')) api.log.info('tick', await api.store.get('runs'));
    });

    // 6. cleanup hook, runs on disable/unload/reload
    api.dispose('close-connection', async () => {
      api.log.debug('cleanup');
    });
  },

  async onEnable(api) {
    api.log.info('enabled');
  },

  async onDisable(api) {
    await api.store.flush();
    api.log.info('disabled');
  },

  async onUnload(api) {
    api.log.info('unloaded');
  },
});
